{
  "root": "page",
  "elements": {
    "page": {
      "type": "PortfolioPage",
      "props": {
        "profile": { "$state": "/profile" },
        "design": {
          "layout": "library",
          "palette": "graphite",
          "font": "sans"
        },
        "referenceIds": [],
        "motion": "showcase",
        "rationale": "데이터 분석가이므로 논리적 흐름과 구조를 강조하는 library 레이아웃을 선택했습니다. 어두운 그래파이트 톤은 전문성을, 산세리프는 가독성을 높입니다."
      },
      "children": [
        "intro",
        "index",
        "section-block-heat",
        "section-rain-series",
        "section-green-access",
        "career",
        "evidence",
        "contact"
      ]
    },
    "intro": {
      "type": "NameIntro",
      "props": {
        "profile": { "$state": "/profile" },
        "sections": { "$state": "/sections" },
        "sourceId": "watermelon-hero-12"
      },
      "children": []
    },
    "index": {
      "type": "ProjectIndex",
      "props": {
        "sections": { "$state": "/sections" },
        "variant": "rows"
      },
      "children": []
    },
    "section-block-heat": {
      "type": "CaseProcess",
      "props": {
        "section": { "$state": "/sectionById/block-heat" },
        "sourceId": "watermelon-feature-1"
      },
      "children": []
    },
    "section-rain-series": {
      "type": "CaseProcess",
      "props": {
        "section": { "$state": "/sectionById/rain-series" },
        "sourceId": "watermelon-feature-4"
      },
      "children": []
    },
    "section-green-access": {
      "type": "CaseTechnical",
      "props": {
        "section": { "$state": "/sectionById/green-access" },
        "sourceId": "watermelon-book"
      },
      "children": []
    },
    "career": {
      "type": "CareerTimeline",
      "props": {
        "career": { "$state": "/career" }
      },
      "children": []
    },
    "evidence": {
      "type": "EvidenceGrid",
      "props": {
        "evidence": { "$state": "/evidence" }
      },
      "children": []
    },
    "contact": {
      "type": "Contact",
      "props": {
        "contact": { "$state": "/contact" }
      },
      "children": []
    }
  }
}
